CREATE TABLE IF NOT EXISTS kfzb_spectator_state(season_id BIGINT NOT NULL REFERENCES kfzb_seasons(id) ON DELETE CASCADE,player_id BIGINT NOT NULL REFERENCES players(id) ON DELETE CASCADE,flower1 INTEGER NOT NULL DEFAULT 8,flower2 INTEGER NOT NULL DEFAULT 6,flower1_bought INTEGER NOT NULL DEFAULT 0,flower2_bought INTEGER NOT NULL DEFAULT 0,free_feast_cards INTEGER NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(season_id,player_id));
CREATE TABLE IF NOT EXISTS kfzb_supports(id BIGSERIAL PRIMARY KEY,season_id BIGINT NOT NULL REFERENCES kfzb_seasons(id) ON DELETE CASCADE,player_id BIGINT NOT NULL REFERENCES players(id) ON DELETE CASCADE,match_id BIGINT NOT NULL REFERENCES kfzb_matches(id) ON DELETE CASCADE,round_key INTEGER NOT NULL,target_competitor_id BIGINT NOT NULL,potential_ticket INTEGER NOT NULL,rewarded SMALLINT NOT NULL DEFAULT 0,taken BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(season_id,player_id,match_id,round_key));
